<script lang="ts">
  import { onMount,tick } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import type { PrinterSnapshot,PrinterAction,PrintJob,DiscoveredPrinter } from './printers';
  let snapshot=$state<PrinterSnapshot|null>(null),busy=$state(false),refreshing=$state(false),jobsLoading=$state(false),error=$state(''),message=$state(''),busyLabel=$state('');
  let name=$state('Office_Printer'),uri=$state('ipp://printer.local/ipp/print'),model=$state('everywhere'),discoveredId=$state<string|null>(null);
  let queue=$state<string|null>(null),jobs=$state<PrintJob[]>([]),jobError=$state('');
  let confirmation=$state<{action:PrinterAction;message:string}|null>(null);
  let alive=true,revision=0;
  $effect(()=>{if(confirmation)void tick().then(()=>document.getElementById('printer-confirmation')?.focus());});
  async function refresh(clear=true){if(busy||refreshing)return;refreshing=true;const token=revision;try{const next=await invoke<PrinterSnapshot>('get_printers');if(alive&&token===revision){snapshot=next;if(clear)error='';if(queue&&!next.printers.some(printer=>printer.name===queue)){queue=null;jobs=[];}}}catch(cause){if(alive&&token===revision)error=String(cause);}finally{if(alive)refreshing=false;}}
  async function loadJobs(target:string,reveal=true){if(busy||jobsLoading)return;queue=target;jobsLoading=true;jobError='';const token=revision;try{const next=await invoke<PrintJob[]>('get_print_jobs',{name:target});if(alive&&queue===target&&token===revision){jobs=next;if(reveal){await tick();document.getElementById('printer-jobs')?.focus();}}}catch(cause){if(alive&&queue===target)jobError=String(cause);}finally{if(alive)jobsLoading=false;}}
  async function apply(action:PrinterAction){if(busy)return;revision++;busy=true;error='';message='';confirmation=null;busyLabel=action.type==='discover'?'Looking for printers…':action.type==='load_drivers'?'Loading installed drivers…':'Updating the print service…';try{const next=await invoke<{snapshot:PrinterSnapshot;message:string}>('apply_printer',{action});if(alive){snapshot=next.snapshot;message=next.message;if(action.type==='install'||action.type==='install_discovered')discoveredId=null;}}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;busyLabel='';if(queue)void loadJobs(queue,false);}}}
  async function configure(device:DiscoveredPrinter){discoveredId=device.id;name=device.suggested_name;uri=device.uri;model='everywhere';error='';await tick();document.getElementById('printer-name')?.focus();}
  function install(){void apply(discoveredId?{type:'install_discovered',id:discoveredId,name:name.trim(),model}:{type:'install',name:name.trim(),uri:uri.trim(),model});}
  onMount(()=>{void refresh();const status=window.setInterval(()=>void refresh(false),15000);const timer=window.setInterval(()=>{if(queue&&!busy&&!refreshing)void loadJobs(queue,false);},5000);return()=>{alive=false;revision++;window.clearInterval(status);window.clearInterval(timer);};});
</script>
<div class="page-heading"><div><div class="eyebrow">FROM SCREEN TO PAPER</div><h1>Printers</h1><p>Connect printers, manage queues, and check your print jobs.</p></div><button class="quiet" disabled={busy||refreshing} onclick={()=>refresh()}>Refresh printers</button></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}{#if busyLabel}<div class="notice print-notice" role="status">{busyLabel}</div>{/if}
{#if confirmation}<section id="printer-confirmation" tabindex="-1" class="printer-prompt" role="group" aria-label="Confirm printer action"><h2>Confirm printer action</h2><p>{confirmation.message}</p><button class="quiet" onclick={()=>confirmation=null}>Keep current state</button><button class="quiet" onclick={()=>{if(confirmation)void apply(confirmation.action);}}>Confirm printer action</button></section>{/if}
{#if snapshot}
  {#if !snapshot.scheduler_running}<div class="notice print-notice" role="status">The CUPS print service is not running. Start the service, then refresh printers.</div>{/if}
  {#each snapshot.warnings as warning}<div class="notice print-notice" role="status">{warning}</div>{/each}
  <section class="section"><h2>Configured printers</h2><div class="settings-card">{#each snapshot.printers as printer}<div class="printer-row"><div class="printer-heading"><div><strong>{printer.name}</strong>{#if printer.is_default}<span class="default-badge">DEFAULT</span>{/if}<p>{printer.enabled?'Processing enabled':'Paused'} · {printer.accepting_jobs===null?'Job acceptance unknown':printer.accepting_jobs?'Accepting jobs':'Rejecting jobs'} · {printer.state}</p>{#if printer.device_uri}<p>{printer.device_uri}</p>{/if}</div><button class="quiet" disabled={busy||jobsLoading} aria-label={`View jobs for ${printer.name}`} onclick={()=>loadJobs(printer.name)}>View jobs</button></div><div class="printer-actions">{#if !printer.is_default}<button class="quiet" disabled={busy} aria-label={`Make ${printer.name} default`} onclick={()=>confirmation={action:{type:'set_default',name:printer.name},message:`Make ${printer.name} the default printer on your configured print service?`}}>Make default</button>{/if}<button class="quiet" disabled={busy} aria-label={`${printer.enabled?'Pause':'Resume'} ${printer.name}`} onclick={()=>confirmation={action:{type:'set_enabled',name:printer.name,enabled:!printer.enabled},message:printer.enabled?`Pause printing on ${printer.name}? Queued jobs remain, but printing may be interrupted.`:`Resume printing on ${printer.name}? Existing queued jobs may start printing.`}}>{printer.enabled?'Pause printing':'Resume printing'}</button><button class="quiet" disabled={busy||printer.accepting_jobs===null} aria-label={`${printer.accepting_jobs?'Reject':'Accept'} jobs for ${printer.name}`} onclick={()=>{if(printer.accepting_jobs)confirmation={action:{type:'set_accepting',name:printer.name,accepting:false},message:`Reject new jobs for ${printer.name}? Existing jobs remain in its queue.`};else void apply({type:'set_accepting',name:printer.name,accepting:true});}}>{printer.accepting_jobs===null?'Acceptance unknown':printer.accepting_jobs?'Reject new jobs':'Accept new jobs'}</button></div></div>{:else}<div class="setting-row"><p>{snapshot.scheduler_running?'No printers are configured. Find a nearby printer or add one below.':'Configured printers will appear when the print service is available.'}</p></div>{/each}</div></section>
  {#if queue}<section id="printer-jobs" tabindex="-1" class="section"><div class="section-heading"><h2>Jobs · {queue}</h2><div class="printer-actions"><button class="quiet" disabled={busy||jobsLoading} onclick={()=>{if(queue)void loadJobs(queue,false);}}>Refresh jobs</button><button class="quiet" onclick={()=>{queue=null;jobs=[];}}>Close jobs</button></div></div>{#if jobError}<div class="notice error" role="alert">{jobError}</div>{/if}{#if jobsLoading}<p class="description" role="status">Reading queued jobs…</p>{/if}<div class="settings-card">{#each jobs as job}<div class="setting-row"><div><strong>{job.id}</strong><p>{job.owner} · {Math.ceil(job.bytes/1024)} KiB · {job.submitted}</p></div><button class="quiet" disabled={busy||jobsLoading} aria-label={`Cancel print job ${job.id}`} onclick={()=>confirmation={action:{type:'cancel_job',printer:job.printer,id:job.id},message:`Cancel ${job.id}? The queued job will be cancelled; pages already printed cannot be recalled.`}}>Cancel job</button></div>{:else}{#if !jobsLoading&&!jobError}<div class="setting-row"><p>No unfinished print jobs in this queue.</p></div>{/if}{/each}</div></section>{/if}
  <section class="section"><div class="section-heading"><h2>Find printers</h2><button class="quiet" disabled={busy||!snapshot.scheduler_running} onclick={()=>apply({type:'discover'})}>Find printers</button></div><p class="description">Look for available devices and network printers. Discovery runs only when requested.</p><div class="settings-card">{#each snapshot.discovered as device}<div class="setting-row"><div><strong>{device.suggested_name}</strong><p>{device.kind} · {device.uri}</p></div><button class="quiet" disabled={busy} aria-label={`Configure discovered printer ${device.suggested_name}`} onclick={()=>configure(device)}>Configure</button></div>{:else}<div class="setting-row"><p>No unconfigured printers in the current discovery results.</p></div>{/each}</div></section>
  <section class="section"><h2>Add a printer</h2><p class="description">IPP Everywhere works with compatible driverless IPP printers. USB and older printers may need an installed driver.</p>{#if discoveredId}<div class="notice print-notice" role="status">Discovered device selected. Its full address will be used for installation. <button class="quiet" onclick={()=>discoveredId=null}>Use manual address</button></div>{/if}<fieldset disabled={busy||!snapshot.scheduler_running}><legend class="sr-only">Printer installation</legend><div class="settings-card"><div class="setting-row"><div><label for="printer-name">Printer name</label><p>Use letters, numbers, dots, underscores, or hyphens. Choose a unique name; existing queues are checked before installation.</p></div><input id="printer-name" type="text" maxlength="127" bind:value={name} autocomplete="off" /></div><div class="setting-row"><div><label for="printer-uri">Device URI</label><p>Use a printer address without embedded credentials.</p></div><input id="printer-uri" type="text" maxlength="2048" bind:value={uri} disabled={!!discoveredId} autocomplete="off" /></div><div class="setting-row"><div><label for="printer-driver">Driver / model</label><p>Use IPP Everywhere or load drivers registered with your print service.</p></div><select id="printer-driver" bind:value={model}><option value="everywhere">IPP Everywhere</option><option value="raw">Raw · application supplies printer data</option>{#each snapshot.drivers.filter(driver=>!['everywhere','raw'].includes(driver.id)) as driver}<option value={driver.id}>{driver.name}</option>{/each}</select></div><div class="setting-row"><button class="quiet" onclick={()=>apply({type:'load_drivers'})}>Load installed drivers</button><button class="primary" disabled={!name.trim()||!uri.trim()} onclick={install}>Install printer</button></div></div></fieldset></section>
  <p class="footnote">Changes take effect on your configured CUPS print service and may require authorization. No test pages are printed automatically.</p>
{:else if !error}<div class="loading" role="status">Reading the print service…</div>{/if}
<style>
  .printer-row{padding:20px;border-bottom:1px solid var(--fd-border)}.printer-row:last-child{border-bottom:0}.printer-heading{display:flex;justify-content:space-between;align-items:center;gap:15px}.printer-heading>div{min-width:0;overflow-wrap:anywhere}.printer-row strong,.setting-row strong{font-size:13px;font-weight:600}.printer-row p{font-size:11px;color:var(--fd-text-muted);line-height:1.8;margin-top:7px}.printer-actions{display:flex;gap:8px;flex-wrap:wrap}.printer-row>.printer-actions{margin-top:16px}.default-badge{font-size:8px;letter-spacing:1px;border:1px solid var(--fd-border);background:var(--fd-accent-soft);color:var(--fd-accent);padding:5px 7px;border-radius:5px;margin-left:12px}.description,.footnote{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:12px 0 18px}.printer-prompt{padding:22px;border:1px solid var(--fd-border);border-radius:var(--fd-radius);background:var(--fd-surface);margin:22px 0}.printer-prompt p{font-size:12px;line-height:1.8;color:var(--fd-text-muted);margin:12px 0}.printer-prompt button{margin-right:8px}.print-notice{background:var(--fd-accent-soft);color:var(--fd-text-muted);font-size:12px;line-height:1.8}.print-notice button{margin-left:8px}fieldset{border:0;padding:0;margin:0;min-width:0}input,select{font:inherit;font-size:12px;color:var(--fd-text);background:var(--fd-surface);border:1px solid var(--fd-border);border-radius:7px;padding:9px 11px;width:45%;max-width:320px}.primary{background:var(--fd-accent);color:white;padding:10px 14px;border-radius:8px;font-size:12px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.setting-row>div{min-width:0;overflow-wrap:anywhere}@media(max-width:900px){.printer-heading{align-items:flex-start;flex-direction:column}}@media(max-width:600px){input,select{width:100%;max-width:none}}
</style>
